from __future__ import annotations
import base64
import json
import os
import tempfile
from typing import Any
from packaging.version import Version

import requests
from cryptography.hazmat.primitives.serialization import (
    Encoding,
    NoEncryption,
    PrivateFormat,
    pkcs12
)
from taf.internal.impact_radar import log_radar
from taf.nms.netact.ssh_node import SshNode

from .exceptions import ClsApiError, LicenseError, KeycloakApiError
from .keycloak import Keycloak
from .validator import ParametersValidator

requests.packages.urllib3.disable_warnings()  # type: ignore[attr-defined]


class ClsRestApi:
    """
    Centralized License Server (CLS)
    CLS REST API: https://confluence.ext.net.nokia.com/display/NE3S/CLS+RESTful+API
    """
    CERTIFICATE_PATH = r'/opt/nokia/global/cls-backend/CLS-Server-CA/CLS_Client.p12'
    NEW_CERTIFICATE_PATH = r'/d/oss/global/certificate-management/cert-repo/cls.backend/active/keystore/cls.backend.p12'
    CLS_WEB_ENV_PATH = '/opt/oss/Nokia-cls-web/conf/cls-web.env'
    AUTH_V3_CLS_VERSION = '26.2.0.2013'  # CLS version since which Keycloak API (auth v3) is used for authentication

    def __init__(self, node: SshNode, keycloak: Keycloak) -> None:
        self.ssh_node = node
        self.skip_cert = False
        self.username = 'clsadmin'
        try:
            self.password = keycloak.password(
                self.ssh_node, self.username, 'CLS'
            )
        except IOError as e:
            if f'Keycloak admin user {self.username} of realm CLS is not configured' in str(e):
                self.skip_cert = True
                self.username, self.password = node.username, node.password
            else:
                raise
        self.cls_web_env = self.get_cls_web_env()
        self.cls_version = self.cls_web_env.get('cls_version')
        self.cls_url = f'https://{self.hostname}/CLS'
        self._client_certificate: Any = None
        self._private_key = None
        self._public_cert = None

    @property
    def hostname(self) -> str:
        """
        Set IP or FQDN based on the CLS version.

        :return: IP or FQDN
        :rtype: str
        """
        if self.cls_version and Version(self.cls_version) >= Version(self.AUTH_V3_CLS_VERSION):
            return self.get_cls_fqdn() or self.ssh_node.hostname
        return self.ssh_node.hostname

    def get_cls_fqdn(self) -> str | None:
        """
        Retrieve CLS FQDN from the remote node.

        :return: CLS FQDN or None if not found
        :rtype: str | None
        """
        with self.ssh_node as connected_node:
            cls_fqdn = connected_node.fqdn
        return cls_fqdn if cls_fqdn else None

    def get_cls_web_env(self) -> dict:
        """
        Retrieve CLS web environment variables from the remote node.

        :return: dictionary with CLS web environment variables
        :rtype: dict
        """

        with self.ssh_node as connected_node:
            env_content = connected_node.execute_command(
                f'cat {self.CLS_WEB_ENV_PATH}', timeout=60).stdout
        env_vars = {
            'keycloak_server': None,
            'keycloak_realm': None,
            'keycloak_client': None,
            'cls_version': None
        }
        for line in env_content.splitlines():
            if '=' in line:
                key, value = line.split('=', 1)
                key_lower = key.strip().lower()
                if key_lower in env_vars:
                    env_vars[key_lower] = value.strip()
        return env_vars

    def close(self) -> None:
        """

        :return:
        """
        if self._public_cert:
            self._public_cert.close()
        if self._private_key:
            self._private_key.close()

    def _get_client_certificate_content(self, command):
        """
        Gets client certificate content via ssh.

        :param command: command to execute on the remote node
        :return: client certificate content
        :rtype: bytes
        """
        with self.ssh_node as ssh:
            process = ssh.ssh_connection.send_command(command)
            client_certificate = process.stdout.read()
            if not client_certificate:
                stderr = process.stderr.read()
                if stderr:
                    raise IOError(stderr if isinstance(stderr, str) else stderr.decode('utf-8'))
            return client_certificate

    @property
    def client_certificate(self) -> Any:
        """
        Gets client certificate via ssh

        :return: client certificate
        :rtype: pkcs12.PKCS12KeyAndCertificates
        """
        if not self._client_certificate:
            with self.ssh_node as ssh:
                try:
                    cert_command = (f'docker exec cls-services cat {self.CERTIFICATE_PATH} ||'
                                    f'podman exec cls-services cat {self.CERTIFICATE_PATH}')
                    cert_content = self._get_client_certificate_content(cert_command)
                    cert_password = b'changeit'
                    self._client_certificate = pkcs12.load_pkcs12(cert_content, cert_password)
                except (OSError, ValueError):
                    cert_command = f'cat {self.NEW_CERTIFICATE_PATH}'
                    cert_content = self._get_client_certificate_content(cert_command)
                    cert_password_command = (
                        '/opt/oss/Nokia-sm_certificate_lcm_migration/install/bin/getPassword.sh'
                        ' --endpoint cls.backend'
                    )
                    cert_password = ssh.execute_command(cert_password_command).stdout.encode('utf-8')
                    self._client_certificate = pkcs12.load_pkcs12(cert_content, cert_password)
        return self._client_certificate

    @property
    def private_key(self) -> Any:
        """
        :return: private key
        :rtype: tempfile.NamedTemporaryFile
        """
        if not self._private_key:
            private_key_buffer = self.client_certificate.key.private_bytes(
                Encoding.PEM, PrivateFormat.PKCS8, NoEncryption())
            self._private_key = self._create_temp_file(private_key_buffer)
        return self._private_key

    @property
    def public_cert(self) -> Any:
        """
        :return: public certificate
        :rtype: tempfile.NamedTemporaryFile
        """
        if not self._public_cert:
            certificate_buffer = self.client_certificate.cert.certificate.public_bytes(Encoding.PEM)
            self._public_cert = self._create_temp_file(certificate_buffer)
        return self._public_cert

    @staticmethod
    def _create_temp_file(content: bytes, offset: int = 0) -> Any:
        temp_file = tempfile.NamedTemporaryFile()
        temp_file.write(content)
        # After writing, you have to rewind the file handle using seek() in order to read the data back from it
        temp_file.seek(offset)
        return temp_file

    def get_licenses(self,
                     require_unique: bool = False,
                     filters: dict | None = None
                     ) -> tuple[list[dict] | dict, dict | None]:
        """

        :param dict(string, string) filters: parameters for filtering licenses e.g. featureCode=5
            Available filters:
            "serialNumber", "fileName", "code", "name", "mode", "totalCapacity", "usedCapacity", "capacityUnit",
            "type", "startDate", "endDate", "targetType", "targetId", "featureCode", "featureName"
        :param bool require_unique: if True, checks if only one element is found for given filters.
            In case there are multiple elements - raises ClsApiError
            Otherwise - returns the element
        :return: licenses, metadata
        :rtype: tuple(list(dict), dict)
        """
        api_endpoint = f'{self.cls_url}/api/v1/licenses'
        license_attributes = {
            "serialNumber", "fileName", "code", "name", "mode", "totalCapacity",
            "usedCapacity", "capacityUnit", "type", "startDate", "endDate", "targetType",
            "targetId", "featureCode", "featureName"
        }
        if filters:
            ParametersValidator.validate_parameters(license_attributes, filters)
        response = self._request('GET', api_endpoint, params=filters)
        self._check_api_response(response)
        return self._parse_api_response(response, result_key='licenses', require_unique=require_unique)

    def get_features(self,
                     client_id: str,
                     filters: dict | None = None,
                     require_unique: bool = False
                     ) -> tuple[list[dict] | dict, dict | None]:
        """

        :param string client_id: e.g. 'MRBTS-123456'
        :param dict(string, string) filters: parameters for filtering features e.g. featureCode=28444
            Available filters:
            'featureCode', 'capacity', 'type', 'allocations'
        :param bool require_unique: if True, checks if only one element is found for given filters.
            In case there are multiple elements - raises ClsApiError
            Otherwise - returns the element
        :return: features, metadata
        :rtype: tuple(list(dict), dict)
        """
        api_endpoint = f'{self.cls_url}/api/v1/clients/{client_id}/features'
        feature_attributes = {'featureCode', 'capacity', 'type', 'allocations'}
        if filters:
            ParametersValidator.validate_parameters(feature_attributes, filters)
        response = self._request('GET', api_endpoint, params=filters)
        self._check_api_response(response)
        return self._parse_api_response(response, result_key='features', require_unique=require_unique)

    @property
    def authorization(self) -> str:
        """
        Prepare authorization header value for internal CLS API.

        :return: authorization header value
        """
        if self.cls_version and Version(self.cls_version) >= Version(self.AUTH_V3_CLS_VERSION):
            token_type, access_token = self.generate_token()
            return f'{token_type} {access_token}'
        else:
            credentials = f'{self.username}:{self.password}'
            encoded_credentials = base64.b64encode(credentials.encode('utf-8'))
            return f'Basic {encoded_credentials.decode()}'

    def generate_token(self) -> tuple[str, str]:
        """
        Generate Keycloak token for CLS internal API authorization.

        :return: token_type, access_token
        :rtype: tuple[str, str]
        """
        keycloak_server = self.cls_web_env['keycloak_server']
        keycloak_realm = self.cls_web_env['keycloak_realm']
        api_endpoint = f'{keycloak_server}/realms/{keycloak_realm}/protocol/openid-connect/token'
        data = {
            'grant_type': 'password',
            'client_id': self.cls_web_env['keycloak_client'],
            'username': self.username,
            'password': self.password,
        }
        response = self._request('POST', api_endpoint, data=data)
        self._check_keycloak_response(response)
        response_json = response.json()
        return response_json['token_type'], response_json['access_token']

    def unblock_license(self, license_serialnumber: str) -> None:
        """
        Unblock license with given serial number that was previously
        blocked/cancelled by `terminate_license` method.

        :param license_serialnumber: License serial number, e.g.: `9991224064417`
        """
        if self.cls_version and Version(self.cls_version) >= Version(self.AUTH_V3_CLS_VERSION):
            api_endpoint = f'{self.cls_url}/internal/licenses/{license_serialnumber}'
            headers = {'Authorization': self.authorization}
            response = self._request('DELETE', api_endpoint, headers=headers)
            self._check_api_response(response)
        else:
            raise ClsApiError(
                f'Unblocking licenses is supported since CLS {self.AUTH_V3_CLS_VERSION} version, '
                f'while the current version is {self.cls_version}'
            )

    def upload_license(self,
                       license: str,
                       license_name: str | None = None
                       ) -> list[dict] | dict:
        """
        Upload license from given path or file-like object to CLS.

        :param string license: License content or path to license file, e.g.: `/tmp/O1400107.XML`
        :param string license_name: If file is set as license its name will be used by default.
            Otherwise, must be set explicitly, e.g.: `O1400107.XML`.
        :return: license
        :rtype: dict
        """
        api_endpoint = f'{self.cls_url}/internal/licenses/upload'
        headers = {'Authorization': self.authorization}
        files = {'license': self._prepare_license_data(license, license_name)}
        response = self._request('POST', api_endpoint, headers=headers, files=files)
        self._check_api_response(response)
        license_content, _ = self._parse_api_response(response, 'licenses', require_unique=True)
        return license_content

    @staticmethod
    def _prepare_license_data(license: Any,
                              license_name: str | None = None
                              ) -> tuple:
        if os.path.exists(license):
            license_name = license_name or os.path.basename(license)
            with open(license, 'rb') as f:
                license = f.read()
        if not license_name:
            raise LicenseError(
                'license_name is not set, while it is mandatory '
                'if license content is passed as license')
        return license_name, license, 'application/xml'

    def terminate_license(self,
                          license_serialnumber: str | None = None,
                          license_name: str | None = None
                          ) -> tuple[list[dict] | dict, dict | None]:
        """
        Terminate (cancel) license with given serial number or name.

        :param string license_serialnumber: License serial number, e.g.: `9991224064417`
        :param string license_name: License file name, e.g.: `R2100355.XML`
        :return: licenses, metadata
        :rtype: tuple(list(dict), dict)
        """
        api_endpoint = f'{self.cls_url}/internal/licenses/cancel'
        headers = {
            'Authorization': self.authorization,
            "Content-Type": "application/vnd.nokia-cls-license.text+json"
        }
        filters = self._create_filters(license_serialnumber, license_name)
        licenses, _ = self.get_licenses(filters=filters, require_unique=False)
        if licenses:
            data = json.dumps({"licenses": licenses})
            response = self._request('POST', api_endpoint, headers=headers, data=data)
            self._check_api_response(response)
            return self._parse_api_response(response, result_key="licenses")
        else:
            exc_msg = f'License with {list(filters.keys())[0]!r} = {list(filters.values())[0]!r} is not active.'
            raise ClsApiError(exc_msg)

    @staticmethod
    def _create_filters(
            license_serialnumber: str | None,
            license_name: str | None) -> dict:
        if not license_serialnumber and not license_name:
            raise TypeError('License serial number or license file name must be passed to terminate it.')
        elif license_serialnumber:
            return {'serialNumber': license_serialnumber}
        else:
            return {'fileName': license_name}

    def _request(self,
                 method: str,
                 api_endpoint: str,
                 headers: dict | None = None,
                 data: dict | bytes | str | None = None,
                 params: dict | None = None,
                 files: dict | tuple | None = None
                 ) -> requests.Response:

        if isinstance(data, dict) and "password" in data:
            radar_request_data = data.copy()
            radar_request_data["password"] = "*" * len(data["password"])
        else:
            radar_request_data = data  # type: ignore
        log_radar(
            "Sending NetAct request",
            request_method=method,
            request_url=api_endpoint,
            request_params=params,
            request_data=radar_request_data,
        )
        return requests.request(
            method,
            api_endpoint,
            headers=headers,
            data=data,
            params=params,
            files=files,
            cert=None if self.skip_cert else (self.public_cert.name, self.private_key.name),
            verify=False
        )

    @staticmethod
    def _get_response_json(response: requests.Response) -> dict | None:
        try:
            response_json = response.json()
        except requests.exceptions.JSONDecodeError:
            return None
        return response_json

    @classmethod
    def _check_keycloak_response(cls, response: requests.Response) -> None:
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as e:
            cls._check_keycloak_errors(response)
            if response.text:
                raise requests.exceptions.HTTPError(
                    f'{e}\nResponse: {response.text}') from e
            raise

    @classmethod
    def _check_keycloak_errors(cls, response: requests.Response) -> None:
        response_json = cls._get_response_json(response)
        if response_json and 'access_token' not in response_json:
            raise KeycloakApiError(f'Token generation failed.\nResponse: {response_json}')

    @classmethod
    def _check_api_response(cls, response: requests.Response) -> None:
        try:
            response.raise_for_status()
        except requests.exceptions.HTTPError as e:
            cls._check_api_errors(response)
            if response.text:
                raise requests.exceptions.HTTPError(
                    f'{e}\nResponse: {response.text}') from e
            raise
        cls._check_api_errors(response)

    @classmethod
    def _check_api_errors(cls, response: requests.Response) -> None:
        response_json = cls._get_response_json(response)
        if response_json and '_embedded' in response_json:
            if 'errors' in response_json['_embedded']:
                raise ClsApiError(response_json['_embedded']['errors'])

    @classmethod
    def _parse_api_response(cls,
                            response: requests.Response,
                            result_key: str,
                            require_unique: bool = False
                            ) -> tuple[list[dict] | dict, dict | None]:
        response_json = response.json()['_embedded']
        metadata_key = 'metadata'
        result = response_json[result_key]
        metadata = response_json.get(metadata_key)
        if require_unique:
            cls._check_if_unique(result)
            result = result[0]
        return result, metadata

    @staticmethod
    def _check_if_unique(result: list) -> None:
        elements_count = len(result)
        if elements_count != 1:
            raise ClsApiError(f'Expected 1 element in result, '
                              f'got {elements_count}:\n{result}')
